<script>
import { createApp } from '@mpxjs/core'
import { createPinia } from '@mpxjs/pinia'

createApp({
  onAppInit () {
    // Create one Pinia instance per app/SSR request. A module-level instance
    // would allow state from one article request to leak into another.
    return { pinia: createPinia() }
  }
})
</script>

